/// @notice Critical: verify getNextSqrtPriceFromInput/Output are inverses
function testFuzz_C11_inputOutputInverse(uint160 sqrtP, uint128 liq, uint256 amount) public pure {
    sqrtP = uint160(bound(sqrtP, MIN_SQRT_RATIO + 1, MAX_SQRT_RATIO - 1));
    liq = uint128(bound(liq, 1e12, type(uint128).max / 2));
    amount = bound(amount, 1, 1e30);

    // Compute new price from input (zeroForOne)
    uint160 newP;
    try SqrtPriceMath.getNextSqrtPriceFromInput(sqrtP, liq, amount, true) returns (uint160 p) {
        newP = p;
    } catch {
        return; // overflow is fine
    }

    if (newP == sqrtP) return; // no movement

    // How much token1 comes out?
    uint256 amountOut = SqrtPriceMath.getAmount1Delta(newP, sqrtP, liq, false);

    // Going back: swap amountOut of token1 back
    uint160 backP;
    try SqrtPriceMath.getNextSqrtPriceFromInput(newP, liq, amountOut, false) returns (uint160 p) {
        backP = p;
    } catch {
        return;
    }

    // backP should be <= sqrtP (rounding means we don't get all the way back)
    assertTrue(backP <= sqrtP + 1, "C11: round-trip should not create value");
}

