function testFuzz_EXP02_roundingDirectionSwap(uint160 startP, uint128 liq, uint256 amountIn) public pure {
    startP = uint160(bound(startP, MIN_SQRT_RATIO + 1000, MAX_SQRT_RATIO - 1000));
    liq = uint128(bound(liq, 1e15, type(uint64).max));
    amountIn = bound(amountIn, 1e6, 1e25);

    // Swap token0 -> token1
    uint160 endP;
    try SqrtPriceMath.getNextSqrtPriceFromInput(startP, liq, amountIn, true) returns (uint160 p) {
        endP = p;
    } catch {
        return;
    }

    if (endP >= startP || endP == 0) return;

    // Amount of token1 user gets (rounded DOWN — user gets less)
    uint256 amount1Out = SqrtPriceMath.getAmount1Delta(endP, startP, liq, false);

    // Amount of token0 needed to produce that token1 (rounded UP — user pays more)
    uint256 amount0Needed = SqrtPriceMath.getAmount0Delta(endP, startP, liq, true);

    // User paid amountIn, needed amount0Needed
    // If amountIn < amount0Needed, user got a discount — BAD
    // But getNextSqrtPrice already accounts for this:
    // endP = f(startP, liq, amountIn) is computed to be conservative
    assertTrue(amountIn >= amount0Needed - 1, "EXP-02: user underpaid for swap");
}

